DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_1','Pigeon Republic[NEWLINE]Protected land trade and distributed origin-city yields[NEWLINE]Science or Culture; Diplomacy with a strong trade economy[NEWLINE][NEWLINE]Establish safe outgoing caravans, then decide whether to concentrate route yields or activate several Roost cities. The bonus belongs to the origin of a qualifying land route, and domestic routes are fully useful.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_2','Use the Carrier Pigeon''s sight to find safe routes and defensible destinations. Establish normal food and production first; protect a caravan before making the economy depend on its recurring Science and Culture.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_3','Place Roosts in real land-route origins. Concentrating routes can support a strong research city; distributing them can activate several separate Production bonuses. Check that each route remains active after a war or access change.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_4','Maintain land-route capacity and the cities that multiply its output. The Renaissance increases the recurring route yields, but maritime routes and incoming trade never become substitutes for qualifying caravans.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_5','- Domestic food or Production trade can also provide the signature yields.[NEWLINE]- Several outgoing land routes stack Science and Culture at the origin.[NEWLINE]- Roosts add useful Culture and an active-route Production incentive.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_6','- Plundered, interrupted and missing routes remove the dependent output.[NEWLINE]- Sea and incoming routes do not qualify.[NEWLINE]- A Roost''s conditional Production is a single city bonus, not a bonus per route.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_7','- Patrol or raid caravan corridors and threaten their actual origins.[NEWLINE]- Force unsafe routes or unfavourable destination choices through military pressure.[NEWLINE]- Use maritime advantages on a map where reliable land trading is constrained.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_8','- Counting sea routes or trade arriving in the city.[NEWLINE]- Multiplying the Roost''s Production once for every caravan.[NEWLINE]- Stacking the entire economy in an origin that cannot be defended.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Filthy Realm: A strong domestic caravan network can earn the UA without supplying an easy foreign-trade contamination channel.[NEWLINE][NEWLINE]The Lantern Fleet: On an inland, connected map, qualifying caravans can operate where Maren has few coastal snapshot opportunities.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Fast land units can threaten caravans and move between exposed origin cities.[NEWLINE][NEWLINE]McPvP: Mobile objective forces can contest the same land corridors the trade network needs to keep safe.');
