INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_LEADER_BACKGROUND','Establish safe outgoing caravans, then decide whether to concentrate route yields or activate several Roost cities. The bonus belongs to the origin of a qualifying land route, and domestic routes are fully useful.');
