INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_STRATEGY','Establish safe outgoing caravans, then decide whether to concentrate route yields or activate several Roost cities. The bonus belongs to the origin of a qualifying land route, and domestic routes are fully useful.[NEWLINE][NEWLINE]Use the Carrier Pigeon''s sight to find safe routes and defensible destinations. Establish normal food and production first; protect a caravan before making the economy depend on its recurring Science and Culture.[NEWLINE][NEWLINE]Place Roosts in real land-route origins. Concentrating routes can support a strong research city; distributing them can activate several separate Production bonuses. Check that each route remains active after a war or access change.[NEWLINE][NEWLINE]Maintain land-route capacity and the cities that multiply its output. The Renaissance increases the recurring route yields, but maritime routes and incoming trade never become substitutes for qualifying caravans.');
