INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_LEADER_TEXT_2','Use the Carrier Pigeon''s sight to find safe routes and defensible destinations. Establish normal food and production first; protect a caravan before making the economy depend on its recurring Science and Culture.[NEWLINE][NEWLINE]Place Roosts in real land-route origins. Concentrating routes can support a strong research city; distributing them can activate several separate Production bonuses. Check that each route remains active after a war or access change.[NEWLINE][NEWLINE]Maintain land-route capacity and the cities that multiply its output. The Renaissance increases the recurring route yields, but maritime routes and incoming trade never become substitutes for qualifying caravans.');
