INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFPIGEONS_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Filthy Realm: A strong domestic caravan network can earn the UA without supplying an easy foreign-trade contamination channel.[NEWLINE][NEWLINE]The Lantern Fleet: On an inland, connected map, qualifying caravans can operate where Maren has few coastal snapshot opportunities.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Fast land units can threaten caravans and move between exposed origin cities.[NEWLINE][NEWLINE]McPvP: Mobile objective forces can contest the same land corridors the trade network needs to keep safe.');
